//------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------ 
//	NAME:			Forbruk                                                                                                                                                                                                                                                                          
//	CREATOR:		Helgevold - William Veim                                                                                                                                                                                                                                                              
//                                                                                                                                                                                                                                                                                                                            
//------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------ 
//  VERSION LOG:                                                                                                                                                                                                                                                                                                   
//	VERSION			DATE					SIGN						DESCRIPTION                                                                                                                                                                                                                                 
//	1.0.0					2023-03-01			William Veim			Initial release                                                                                                                                                                                                                                  
//	2.0.0					2025-04-15			William Veim			ReWork
//	2.0.1					2025-09-08		 	William Veim			Rework initialising variables
//	2.1.0					2026-04-29		  	William Veim			Added input and logic for process TAG
//
//===============================================================================================================================
//
//		BESKRIVELSE:
//		Regner ut forbrukt mengde i dag, i går og totalt basert på måling av mengde.
//		Ved økning i mengde tolkes dette som en påfylling og stabil mengde etter dette tolkes som fylling fullført. (Gir korrekt mengde idag selv om det har vært påfylling)
//		Brukes til å måle forbrukt mengde av eks oxygen, lut, metanol...
//		
//===============================================================================================================================

(*************************************************************************
 *	IMPORTING SYSTEM VARIABLES
 *************************************************************************)
 
Current_Time := TruncTod(DT_TO_TOD(In:=GetTime()), _SEC);
DtToDateStruct(In:=GetTime(), DateStruct=>DateStruct);

(*************************************************************************
 *	INITIALISING VARIABELS
 *************************************************************************)

Ext_AccumulatedData.EXT_General.LocationIndex[0]:=Cfg_MainLocation; //First index / main location is forced; remaining tree optional can be set in SCADA
Ext_AccumulatedData.EXT_General.Process_TAG:= Cfg_ProcessTAG;
Ext_AccumulatedData.EXT_Engineering.ConversationFactor_Visible:=FALSE; //NOT in use

IF NOT EXT_AccumulatedData.INT_Data.Initialise THEN
	
	//Engeneering parameter
	EXT_AccumulatedData.EXT_Engineering.ConversationFactor:=0;
	EXT_AccumulatedData.EXT_Engineering.Unit:='';

	//Init complete
	EXT_AccumulatedData.INT_Data.Initialise:=TRUE;

END_IF;

//Initialise reset date on first data input
IF EXT_AccumulatedData.EXT_Engineering.ResetDate_Total = '' AND Inp_Amount<>0 THEN
	
	EXT_AccumulatedData.EXT_Engineering.ResetDate_Total:=DateToString(DT_TO_DATE(GetTime()));
	
END_IF;

(*************************************************************************
 *	INCREMENT AND DATA CONTROL
 *************************************************************************)

// Setter variabler ved programstart
IF P_First_Run OR P_First_RunMode THEN
	Amount_Sample := Inp_Amount;
END_IF;

IF Filling_Ended THEN
	Ext_AccumulatedData.EXT_Statistics.Total_Today := Amount_Midnight - Amount_BeforeFilling + Amount_AfterFilling - Inp_Amount;
ELSE
	Ext_AccumulatedData.EXT_Statistics.Total_Today := Amount_Midnight - Inp_Amount;
END_IF;

//Sikrer at mengde idag ikke kan gå under 0
IF Ext_AccumulatedData.EXT_Statistics.Total_Today < 0 THEN
	Ext_AccumulatedData.EXT_Statistics.Total_Today := 0;
END_IF;

//Sjekker om det pågår fylling
//Låser verdier for før og etter fylling
IF Get1minClk() AND NOT Filling_Ended THEN
	//Sjekker om påfylling starter/pågår
	IF Inp_Amount > Amount_BeforeFilling*1.011 AND NOT Filling_Ongoing THEN
		Filling_Ongoing := TRUE;
		Amount_BeforeFilling := Amount_Sample;
	//Sjekker om fylling er fullført/fylling har vært
	ELSIF Inp_Amount > Amount_Sample * 0.989 AND Inp_Amount < Amount_Sample * 1.011 THEN
		Filling_Ended := TRUE;
		Filling_Ongoing := FALSE;
		Amount_AfterFilling := Inp_Amount;
	END_IF;
	Amount_Sample := Inp_Amount;
END_IF;

(*************************************************************************
 *	DATA RESET
 *************************************************************************)

// Sjekker om det er ny dag
IF Sample_Day <> DateStruct.Day THEN
	IF Ext_AccumulatedData.EXT_Statistics.Total_Today > 0 THEN	
		Ext_AccumulatedData.EXT_Statistics.Total_Yesterday := Ext_AccumulatedData.EXT_Statistics.Total_Today;
		Ext_AccumulatedData.EXT_Statistics.Total_Year := Ext_AccumulatedData.EXT_Statistics.Total_Year + Ext_AccumulatedData.EXT_Statistics.Total_Today;
	ELSE
		Ext_AccumulatedData.EXT_Statistics.Total_Year := Ext_AccumulatedData.EXT_Statistics.Total_Year + Ext_AccumulatedData.EXT_Statistics.Total_Yesterday;
	END_IF;
	Clear(Ext_AccumulatedData.EXT_Statistics.Total_Today);
	Amount_Midnight := Inp_Amount;
	Filling_Ended := FALSE;
END_IF;

// Sjekker om det er ny uke
IF Sample_Week <> GetWeekOfYear(In:=GetTime()) THEN
	Clear(Ext_AccumulatedData.EXT_Statistics.Total_Week);
END_IF;

// Sjekker om det er ny måned
IF Sample_Month <> DateStruct.Month THEN
	Clear(Ext_AccumulatedData.EXT_Statistics.Total_Month);
END_IF;
			
// Sjekker om det er nytt år
IF GetWeekOfYear(In:=GetTime()) = 1 AND Sample_Week <> GetWeekOfYear(In:=GetTime()) THEN
	Clear(Ext_AccumulatedData.EXT_Statistics.Total_Year);
END_IF;
